package com.cryptostrategy.platform.leaderboard.api.model;import com.cryptostrategy.platform.evaluation.api.model.RankingVersion;import com.cryptostrategy.platform.experiment.api.ExperimentId;import java.time.Instant;import java.util.*;public record LeaderboardRevision(LeaderboardRevisionId revisionId,ExperimentId experimentId,long revisionNumber,int topK,RankingVersion rankingVersion,List<LeaderboardEntry> entries,String fingerprint,Instant createdAt){public LeaderboardRevision{Objects.requireNonNull(revisionId);Objects.requireNonNull(experimentId);Objects.requireNonNull(rankingVersion);entries=List.copyOf(entries);Objects.requireNonNull(fingerprint);Objects.requireNonNull(createdAt);if(revisionNumber<1||topK<1||entries.size()>topK)throw new IllegalArgumentException("revision");for(int i=0;i<entries.size();i++)if(entries.get(i).rank()!=i+1||!entries.get(i).revisionId().equals(revisionId)||!entries.get(i).experimentId().equals(experimentId))throw new IllegalArgumentException("entries");}}
